from pathlib import Path
r=Path(sys.argv[1]);w=Path(sys.argv[2]);sys.path.insert(0,str(w/'tools/nr-color'));import hmd_assess as h,assess
def p(f):return json.loads(h.read_json(f)['content'][0]['text'])
base=h.read_json(r/'steps/001/entry.json')
for n in (2,3):
 d=r/f'steps/{n:03}';receipt=p(next(d.glob('capture-get-*.json')))['result'];e=copy.deepcopy(base);e.update(scheduleOrdinal=n,captureSessionDirectory=str(d),terminalReceipt=receipt,manifest=next(a for a in receipt['artifacts'] if a['path']==receipt['manifest']['finalPath']))
 h.save_json(d/'entry.json',e)
 result=subprocess.run([sys.executable,str(r/'direct-offline.py'),str(r),str(w),'validate',str(n)],capture_output=True,text=True);print(result.stdout);h.save_json(d/'validation.json',json.loads(result.stdout))
i=h.read_json(r/'campaign-index.json');h.preserve(r/'campaign-index.json',r/'campaign-index-before-finalization.json');i.update(complete=False,baselineRepeatabilityQualified=False,terminalReason='All 36 captured pairs rejected by the predeclared position tolerance; drift 0.0009765625 to 0.00146484375 engine units, below float32 position scale. Baseline image gate was not reached.')
for n in range(4,70):i['sequences'].append({'scheduleOrdinal':n,'notRunReason':i['terminalReason']})
assess.atomic_json(r/'campaign-index.json',i)
try: h.save_json(r/'analysis-result.json',h.analyse(r/'campaign-index.json',r/'analysis'))
except Exception as e:h.save_json(r/'analysis-unavailable.json',{'error':str(e),'reason':'No pairs satisfied the frozen camera tolerance.'})

